 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify diagonal chevrons whose three consecutive rows have the
    # signature: center, two flanks, center. Join neighboring motifs at
    # their flank level, and vertically join stacked motifs at their center.
    motifs = []
    for r in range(h - 2):
        for c in range(1, w - 1):
            if (grid[r][c] == 2 and grid[r+1][c-1] == 2 and
                grid[r+1][c+1] == 2 and grid[r+2][c] == 2):
                motifs.append((r, c))
    # Adjacent same-height motifs: bridge the two outer flank cells on
    # their common middle row.
    byrow = {}
    for r,c in motifs:
        byrow.setdefault(r, []).append(c)
    for r, centers in byrow.items():
        centers.sort()
        for a,b in zip(centers, centers[1:]):
            if b-a == 5:
                for x in range(a+2, b-1):
                    if out[r+1][x] == 0: out[r+1][x] = 1
    # Vertically stacked motifs sharing a center column: bridge the gap
    # from bottom center of upper motif to top center of lower motif.
    for r,c in motifs:
        for rr,cc in motifs:
            if cc == c and rr > r+2 and grid[r+2][c] == 2 and grid[rr][c] == 2:
                # Only bridge if no intervening motif at same center.
                if not any(c2 == c and r < r2 < rr for r2,c2 in motifs):
                    for y in range(r+3, rr):
                        if out[y][c] == 0: out[y][c] = 1
    return out
"
}

